package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.DurationFieldType;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.joda.time.impl.DurationFieldTypeImpl;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class MutableDateTime_add_TriageGen0Test {

    @Test
    public void testAdd_WithYears() {
        // Initialize at 2020-01-01
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        long originalMillis = dt.getMillis();

        // Add 5 years
        dt.add(DurationFieldType.year(), 5);

        // Verify year changed
        assertEquals(2025, dt.getYear());
        // Verify other fields remained same
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAdd_WithMonths() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);

        // Add 3 months
        dt.add(DurationFieldType.monthOfYear(), 3);

        assertEquals(4, dt.getMonthOfYear());
    }

    @Test
    public void testAdd_WithDays() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);

        // Add 10 days
        dt.add(DurationFieldType.dayOfMonth(), 10);

        assertEquals(11, dt.getDayOfMonth());
    }

    @Test
    public void testAdd_WithHours() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 10, 0, 0, 0);

        // Add 2 hours
        dt.add(DurationFieldType.hourOfDay(), 2);

        assertEquals(12, dt.getHourOfDay());
    }

    @Test
    public void testAdd_WithMinutes() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 10, 30, 0, 0);

        // Add 15 minutes
        dt.add(DurationFieldType.minuteOfHour(), 15);

        assertEquals(45, dt.getMinuteOfHour());
    }

    @Test
    public void testAdd_WithSeconds() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 10, 30, 15, 0);

        // Add 45 seconds
        dt.add(DurationFieldType.secondOfMinute(), 45);

        assertEquals(0, dt.getSecondOfMinute());
        assertEquals(10, dt.getMinuteOfHour()); // Minute should roll over
    }

    @Test
    public void testAdd_WithMillis() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 10, 30, 15, 500);

        // Add 500 millis
        dt.add(DurationFieldType.millisOfSecond(), 500);

        assertEquals(0, dt.getMillisOfSecond());
        assertEquals(16, dt.getSecondOfMinute()); // Second should roll over
    }

    @Test
    public void testAdd_WithNegativeAmount() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);

        // Subtract 1 year
        dt.add(DurationFieldType.year(), -1);

        assertEquals(2019, dt.getYear());
    }

    @Test
    public void testAdd_WithZeroAmount() {
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        long originalMillis = dt.getMillis();

        // Adding 0 should result in no change (covers the if (amount != 0) branch)
        dt.add(DurationFieldType.year(), 0);

        assertEquals(originalMillis, dt.getMillis());
    }
}
